// Get the "output" field
let rawOutput = $input.first().json.output;

// If the output is wrapped in ```json ... ```
if (typeof rawOutput === "string") {
  rawOutput = rawOutput.trim();

  // Remove code block formatting if present
  rawOutput = rawOutput.replace(/^```json\s*/i, "").replace(/```$/i, "");

  try {
    // Try parsing as JSON
    rawOutput = JSON.parse(rawOutput);
  } catch (e) {
    // If not parsable, wrap in a JSON object
    rawOutput = { output: rawOutput };
  }
}

// Ensure final JSON format
return {output:rawOutput };

// This code processes the output from your AI Agent node.

// 1. Access the data sent from the previous node.
const aiResponseData = $input.first().json.output;
// 2. Extract the message body and the buttons array.
const messageBody = aiResponseData.output;
const buttons = aiResponseData.buttons;

// 3. Check if the 'buttons' array exists and contains at least one button.
if (buttons && Array.isArray(buttons) && buttons.length > 0) {

  // --- IF BUTTONS EXIST: Build and return the WhatsApp message JSON ---

  const recipientPhoneNumber = aiResponseData.order.phone; // Get phone number from the order

  const buttonPayload = {
    to: recipientPhoneNumber,
    type: "button",
    header: {
      text: "The Golden Bowl ✨"
    },
    body: {
      text: messageBody
    },
    footer: {
      text: "Please make a selection"
    },
    action: {
      buttons: buttons.map((btn, index) => ({
        type: "quick_reply",
        title: btn.title,
        id: btn.title.toLowerCase().replace(/[^a-zA-Z0-9]/g, '_') + `_${index}` // Create a unique ID
      }))
    }
  };

  // Return the complete JSON object for the button message.
  return [{ json: {Output:buttonPayload}
     }];

} else {

  // --- IF NO BUTTONS EXIST: Return a simple JSON object with "No" ---

  // This fulfills the "or NO" requirement.
  return [{
    json: {
      output: "No"
    }
  }];
}

